@lru_cache(maxsize=1)
def load_preflop_174_data() -> dict:
    try:
        raw = lzma.decompress(base64.b64decode(_DATA_B64, validate=True))
        data = json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise RuntimeError("The embedded 174-scenario preflop data is corrupt") from exc
    if data.get("schema_version") != 2 or data.get("scenario_count") != 174:
        raise RuntimeError("The embedded 174-scenario preflop data has an unsupported schema")
    scenarios = data.get("scenarios")
    if not isinstance(scenarios, list) or len(scenarios) != 174:
        raise RuntimeError("The embedded preflop data does not contain all 174 scenarios")
    if len(data.get("hand_order", [])) != 169:
        raise RuntimeError("The embedded preflop data does not contain all 169 hand classes")
    ids = [int(item.get("id", -1)) for item in scenarios]
    if len(set(ids)) != 174 or set(ids) != set(range(128, 302)):
        raise RuntimeError("The embedded preflop source IDs are incomplete or duplicated")
    for item in scenarios:
        if len(item.get("hands", [])) != 169:
            raise RuntimeError(f"Scenario #{item.get('id')} does not contain 169 hand classes")
        options = item.get("action_options", [])
        for row in item["hands"]:
            if row:
                if any(int(index) < 0 or int(index) >= len(options) for index, _ in row):
                    raise RuntimeError(f"Scenario #{item.get('id')} has an invalid action option index")
                total = sum(float(freq) for _, freq in row)
                if not 0.999 <= total <= 1.001:
                    raise RuntimeError(f"Scenario #{item.get('id')} has a non-normalized measured hand")
    return data
